// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2017, "4-5", [{"author":"Е. Муравенко","question":"В стихотворении Александра Шибаева о буквах есть такие двустишия:\nБукву «…» в спортивном зале\nПерекладиной назвали.\n\nБуква «…» — с большим брюшком,\nВ кепке с длинным козырьком.\nКакие буквы надо поставить вместо пропусков?","choices":["П, Ь","П, Б","Г, Р","П, В","Т, Б."],"key":"Б","review":["Буквы из стихотворения","Нарисуй перекладину на двух стойках. Получится буква «П», значит, первый пропуск можно сразу заполнить.","Теперь нарисуй ствол буквы и круглое брюшко внизу. Добавь сверху козырёк, вытянутый вправо. Получится буква «Б»."]},{"author":"Л. Фёдорова","question":"В каком имени больше всего слогов?","choices":["<em>Юлия</em>","<em>Марья</em>","<em>Ульяна</em>","<em>Евгения</em>","<em>Светлана</em>."],"key":"Г","review":["Слоги в именах","Считай гласные буквы, потому что в каждом слоге одна гласная. В имени «Марья» две, а в «Юлия», «Ульяна» и «Светлана» по три.","В имени «Евгения» четыре гласные, «е», «е», «и», «я». Поэтому у него больше всего слогов."]},{"author":"Е. Муравенко","question":"<em>Дедушка водит Аню в детский сад</em>.\n<em>Папа очень хорошо водит машину</em>.\n<em>Саша водит собаку на поводке</em>.\n<em>Мы играем в прятки, Миша водит</em>.\n<em>Даня учится читать и водит пальцем по строчкам</em>.\nКого точно можно назвать водителем?","choices":["дедушку","папу","Сашу","Мишу","Даню."],"key":"Б","review":["Кого назвать водителем","Заметь, что «водить» можно по-разному. Можно вести ребёнка, держать собаку на поводке, быть водящим в игре или двигать пальцем по строке.","Водителем в обычной речи называют того, кто управляет транспортом. Из перечисленных людей машину водит папа."]},{"author":"Б. Иомдин","question":"Каким из этих знаков препинания нередко заканчиваются предложения?","choices":["…","«","—","(",";"],"key":"А","review":["Знак, завершающий фразу","Проверь, какие знаки из списка ожидают продолжения. Открывающая кавычка и скобка начинают вставку, а тире и точка с запятой часто разделяют части предложения.","Многоточие может завершить фразу, если мысль осталась недосказанной. Его и ставят, например, на месте затихающих слов."]},{"author":"Б. Иомдин","question":"В Московском институте садоводства вывели <em>земклунику</em>. А что это?","choices":["овощ","фрукт","ягода","орех","гриб."],"key":"В","review":["Название земклуники","Раздели название на «зем-» и «-клуника». В нём слышатся слова «земляника» и «клубника».","Так назвали растение, полученное от скрещивания садовой земляники с клубникой. Его плоды в обычной речи называются ягодами."]},{"author":"И. Иткин","question":"Число 5 больше числа 4, но в слове <em>четыре</em> больше букв, чем в слове <em>пять</em>. Какая ещё пара устроена так же?","choices":["2 —3","5 — 6","7 — 8","9 — 10","11 — 12."],"key":"Д","review":["Числа и длина слов","Сравни длину названий первых четырёх пар. «Два» и «три» одинаковы по длине, как «девять» и «десять». В парах 5 и 6, 7 и 8 у большего числа название тоже длиннее.","Остались 11 и 12. В «одиннадцать» 11 букв, а в «двенадцать» 10. Тут большее число называется более коротким словом."]},{"author":"Б. Иомдин","question":"Что часто встречается?","choices":["агентство кладов","бюро находок","контора потерь","офис пропаж","стол поисков."],"key":"Б","review":["Куда попадают находки","Вспомни, как называют место, куда сдают найденные вещи. Название такого учреждения должно быть знакомым сочетанием двух слов.","Это «бюро находок». Туда можно отнести, например, забытый кем-то зонт, чтобы его смог забрать владелец."]},{"author":"Е. Муравенко","question":"В данных словах буквы а и о заменены прочерками. В каком из слов пропущены две буквы а и одна буква о?","choices":["<em>к_р_в_</em>","<em>г_л_в_</em>","<em>п_д_р_к</em>","<em>п_р_в_з</em>","<em>с_м_к_т</em>."],"key":"Д","review":["Гласные в словах","Впиши пропущенные буквы в первые четыре слова. В «корова», «голова» и «подарок» на этих местах по два «о» и одному «а». В «паровоз» получается такой же подсчёт.","В слове «самокат» последовательность в пропусках — «а», «о», «а». Только здесь две буквы «а» и одна буква «о»."]},{"author":"Б. Иомдин","question":"К какому слову нельзя добавить <em>э</em> и получить новое слово?","choices":["<em>тот</em>","<em>та</em>","<em>то</em>","<em>те</em>","<em>так</em>."],"key":"Г","review":["Где пригодится буква «э»","Попробуй поставить «э» перед каждым словом. Можно получить «этот», «эта», «это» и «этак».","Если приписать букву к «те», выйдет «эте». Правильная форма — «эти», но для неё пришлось бы ещё заменить «е» на «и»."]},{"author":"Н. Петрова","question":"В русском языке кошка мяукает, а в литовском она miaukia. Что по-литовски делают коза, корова и свинья?\n<u>Примечание</u>: ū читается как долгий <em>у</em>.","choices":["kriuksi, mūkia, mekena","mekena, kriuksi, mūkia","mūkia, kriuksi, mekena","mekena, mūkia, kriuksi","mūkia, mekena, kriuksi."],"key":"Г","review":["Голоса на литовском","Прислушайся к голосам животных. Коза блеет «ме», поэтому ей подходит «mekena», а корова мычит «му», поэтому ей подходит «mūkia».","У свиньи слышится хрюканье, которому соответствует «kriuksi». В порядке коза, корова, свинья получается «mekena, mūkia, kriuksi»."]},{"author":"Е. Муравенко","question":"Пёс Пиф из сказки Григория Остера «Приключения Пифа» привык понимать все слова в прямом значении. Он понимает, что <em>брать</em> можно, например, <em>косточку</em> или <em>корзинку</em>. А вот как <em>брать след</em>, так и не понял. Какое ещё выражение Пиф вряд ли поймёт правильно?","choices":["<em>брать книги</em>","<em>брать тетради</em>","<em>брать уроки</em>","<em>брать портфель</em>","<em>брать карандаши</em>."],"key":"В","review":["Что Пиф может брать","Спроси себя, можно ли поднять то, о чём говорится. Книги, тетради, портфель и карандаши можно взять руками.","«Брать уроки» значит заниматься с учителем, например учиться играть на пианино. Уроки нельзя поднять и унести, поэтому Пиф мог бы понять эти слова неверно."]},{"author":"Е. Муравенко","question":"<em>— Мама, а глаза бывают коричневые? — Да, тогда говорят, что глаза … .</em>\n<em>— А волосы? — Волосы … .</em>\n<em>— И шерсть у животных тоже такая? Медведь какой? — А медведь … .</em>","choices":["<em>каштановые</em>, <em>карие</em>,<em>бурый</em>","<em>бурые</em>, <em>каштановые</em>, <em>карий</em>","<em>карие</em>, <em>бурые</em>,<em>каштановый</em>","<em>карие</em>, <em>каштановые</em>, <em>бурый</em>","<em>бурые</em>, <em>карие</em>, <em>каштановый</em>."],"key":"Г","review":["Разные оттенки коричневого","Вспомни, как по-разному называют оттенки коричневого. О коричневых глазах говорят «карие», а о коричневых волосах — «каштановые».","Лесного медведя с такой шерстью называют бурым. В нужном порядке получается «карие, каштановые, бурый»."]},{"author":"С. Сай","question":"Судя по происхождению слова <em>мешок</em>, раньше похожие предметы делали из … .","choices":["коры деревьев","шкур животных","листьев","панциря черепахи","рыбьего пузыря."],"key":"Б","review":["Из чего делали мешки","Сравни слова «мешок» и «мех». Звуки «х» и «ш» могут меняться в родственных словах, как в паре «мех — мешок».","В старину «мехом» называли в том числе бурдюк, то есть сумку из выделанной шкуры. Слово «мешок» связано с этим старым названием, поэтому подходит вариант «из шкур животных»."]},{"author":"Е. Бикмаев","question":"В какой паре даны разнокоренные слова?","choices":["молодой — моложе","низкий — ниже","резкий — реже","тугой — туже","узкий — у́же"],"key":"В","review":["Похожие формы слов","Прочитай формы со смыслом сравнения. «Моложе» — более молодой, «ниже» — более низкий, «туже» — более тугой, «у́же» — более узкий.","«Реже» значит «более редко» и образовано от «редкий». От «резкий» получится «резче», поэтому пара «резкий — реже» разнокоренная."]},{"author":"Е. Бикмаев","question":"Когда на электронных часах 16:00, то можно сказать: «Сейчас четыре часа». А что должны показывать часы, чтобы на вопрос «Который час?» можно было ответить, не называя число?","choices":["10:00","13:00","14:00","15:00","18:00."],"key":"Б","review":["Час без числа","Переведи показания на обычную речь. В 10:00 говорят «десять утра», в 14:00 — «два часа дня», в 15:00 — «три часа дня», в 18:00 — «шесть вечера».","В 13:00 можно просто сказать «час дня». Слово «час» без числа здесь само даёт понять, что речь об одном часе после полудня."]},{"author":"Б. Иомдин","question":"В каком предложении слово <em>человек</em> значит не то, что в остальных?","choices":["<em>У калитки стоял какой-то человек в шляпе.</em>","<em>Человек остановился и посмотрел на меня.</em>","<em>Мне показалось ― человек сейчас заплачет.</em>","<em>В её квартире жил ещё один человек.</em>","<em>Человек ещё в древности научился сверлить камни.</em>"],"key":"Д","review":["Кого обозначает «человек»","Проверь, кого можно представить в каждой фразе. У калитки, на улице и в квартире речь идёт об отдельных людях.","В предложении о сверлении камней рассказывается об умении, которое появилось у людей в древности. Здесь «человек» обозначает человечество в целом."]},{"author":"Б. Иомдин","question":"<em>Коля</em> — <em>Васин друг со школы</em>. Какое утверждение точно верно?","choices":["Коля и Вася вместе учатся в школе.","Коля и Вася вместе работают в школе.","Коля и Вася подружились, когда учились в школе.","Коля учится в школе.","Вася работает в школе."],"key":"В","review":["Друзья со школы","Прочитай «друг со школы» как «друг со школьных лет». В обычном разговоре так указывают на время, когда началась дружба.","В этом смысле Коля и Вася подружились, пока учились в школе. Из фразы нельзя узнать, где они сейчас учатся или работают."]},{"author":"И. Иткин","question":"Футбольный тренер Юрий Павлович Сёмин известен среди болельщиков под шутливым прозвищем Шпалыч. С какой командой Юрий Сёмин добился наибольших успехов?","choices":["«Динамо» (Киев)","«Динамо» (Москва)","«Торпедо»","«Металлист»","«Локомотив»."],"key":"Д","review":["Тренер по прозвищу","Выдели в прозвище Шпалыч слово «шпала». Шпалы лежат под рельсами, поэтому подсказка связана с железной дорогой.","С железной дорогой связано название «Локомотив». Под руководством Сёмина именно этот клуб выиграл чемпионаты России 2002 и 2004 годов."]},{"author":"Л. Федорова","question":"В каком примере пропущено больше всего букв?","choices":["<em>кла_ный ча_</em>","<em>стари_ая гра_ота</em>","<em>ру_кая гра_атика</em>","<em>внекла_ное чте_ие</em>","на месте каждого пропуска пишутся удвоенные согласные."],"key":"В","review":["Буквы в пропусках","Восстанови «классный час», «старинная грамота» и «внеклассное чтение». В пропусках будут «сс» и «с», «нн» и «м», «сс» и «н». Каждая пара даёт три буквы.","В сочетании «русская грамматика» надо вставить «сс» и «мм». Здесь пропущены четыре буквы, больше всего."]},{"author":"Е. Муравенко","question":"В книжке-головоломке Антона Тилипмана «Зубака» во многих словах перепутались буквы. Вот, например, была <em>азбука</em> — стала <em>зубака</em>. Если вы правильно расставите буквы в данных ниже «словах», в четырёх случаях получатся названия птиц, а в одном — нет. В каком?","choices":["<em>волосей</em>","<em>задобрик</em>","<em>усастр</em>","<em>паркоутка</em>","<em>йаканерка.</em>"],"key":"Б","review":["Птицы из перепутанных букв","Переставь буквы в четырёх вариантах. «Волосей» превращается в «соловей», «усастр» — в «страус», «паркоутка» — в «куропатка», «йаканерка» — в «канарейка».","Из оставшегося «задобрик» получается «дикобраз». Это зверь с иглами на спине, поэтому его название выпадает из ряда птиц."]},{"author":"Е. Добрушина","question":"Лёва в социальной сети собрал в группу всех друзей, чья фамилия образована от того же корня, что его. Кроме него, в этот список попали Добряков, Добров, Добрынин и Доброхвалова. Когда Лёва расставил фамилии по алфавиту, то его собственная оказалась в самой середине. Какая фамилия у Лёвы?","choices":["<em>Добрушин</em>","<em>Доброхвалов</em>","<em>Добродеев</em>","<em>Добрин</em>","<em>Добролюбов</em>."],"key":"А","review":["Фамилии по алфавиту","Расположи фамилии друзей по алфавиту. После общей части «Добр» буква «о» идёт раньше «ы» и «я». Получаются Добров, Доброхвалова, Добрынин и Добряков.","Чтобы оказаться третьим, Лёва должен стоять между Доброхваловой и Добрыниным. «Добрушин» начинается на «Добру», а «у» стоит между «о» и «ы»."]},{"author":"И. Иткин","question":"Незнайка пишет окончание -<em>ого</em> через <em>в</em>. Получая письма от Незнайки, Знайка при виде очередной такой ошибки язвительно пишет на полях: «Нет такого слова!». Про какое слово (в написании Незнайки) Знайка так не напишет?","choices":["<em>этого</em>","<em>такого</em>","<em>всякого</em>","<em>большого</em>","Знайка напишет так про все эти слова."],"key":"Б","review":["Как пишет Незнайка","Замени «г» на «в» и прочитай результаты. Получаются «этово», «таково», «всяково» и «большово».","Из этих записей самостоятельное слово только «таково». Можно сказать «таково правило», то есть «правило такое». Поэтому написать «нет такого слова» о форме «таково» нельзя."]},{"author":"Б. Иомдин","question":"В каком случае уменьшительное слово соотносится с исходным не так, как в остальных?","choices":["<em>постелька</em>","<em>колыбелька</em>","<em>кастрюлька</em>","<em>медалька</em>","<em>спиралька</em>."],"key":"В","review":["Уменьшительные слова","Вернись от уменьшительных форм к исходным. «Постелька», «колыбелька», «медалька» и «спиралька» образованы от слов «постель», «колыбель», «медаль» и «спираль».","Все четыре исходных слова оканчиваются на «ь». Исходное слово для «кастрюльки» — «кастрюля», где после мягкого «л» есть ещё гласный звук."]},{"author":"Л. Фёдорова","question":"Какое из слов <strong>не</strong> образует устойчивого словосочетания со словом <em>зрение</em>?","choices":["<em>точка</em>","<em>угол</em>","<em>поле</em>","<em>обман</em>","<em>все слова в (А)‒(Г) образуют с ним устойчивые сочетания.</em>"],"key":"Д","review":["Сочетания со зрением","Подставь «зрения» к первым двум словам. «Точка зрения» — это мнение, а «угол зрения» может обозначать направление, под которым смотрят на предмет.","Есть и «поле зрения», то есть то, что охватывает взгляд, и «обман зрения», когда глаза показывают предмет иначе, чем он выглядит на самом деле. Получаются все четыре сочетания."]},{"author":"Б. Иомдин","question":"В XVI веке один английский издатель предложил для некоторых предложений использовать особый знак. Из пяти данных ниже вопросов учителей он подошёл бы к четырём. Определив его предназначение, выберите, для какого вопроса этот знак <strong>не</strong> подходит.","choices":["<em>А голову ты дома не забыл</em><strong><em>⸮</em></strong>","<em>Оценку вам тоже одну на двоих ставить</em><strong><em>⸮</em></strong>","<em>Уроки за тебя Пушкин делать будет</em><strong><em>⸮</em></strong>","<em>Ты сделал домашнее задание⸮</em>","<em>Третья парта, я вам не мешаю разговаривать</em><strong><em>⸮</em></strong>"],"key":"Г","review":["Особый знак в вопросе","Сравни, чего ждут учителя от ученика. Реплики про забытую голову, общую оценку, Пушкина и разговор за партой звучат как шутливые упрёки. Их смысл и без ответа понятен.","Вопрос «Ты сделал домашнее задание?» задают, чтобы узнать «да» или «нет». Поэтому для него не подходит особый знак для вопросов, которые не требуют ответа."]},{"author":"Е. Муравенко","question":"Маша набрала на компьютере слова труд, трюк, турок, тара, кот, а шутник Яша заменил в них все буквы т одной и той же другой буквой. Как ни удивительно, после этого программа проверки орфографии подчеркнула как неправильное лишь одно слово. Какое Машино слово превратилось в неправильное?","choices":["<em>труд</em>","<em>трюк</em>","<em>турок</em>","<em>тара</em>","<em>кот</em>."],"key":"А","review":["Буквенная шутка Яши","Найди букву, которая помогает сразу в нескольких словах. Если в «трюк» и «турок» заменить «т» на «к», получится «крюк» и «курок».","Та же замена даёт «кара» из «тара» и «кок» из «кот». Коком называют повара на судне. Из «труд» выходит «круд», поэтому программа отметит это слово."]},{"author":"Б. Иомдин","question":"Про что в Словаре Академии Российской 1789 г. говорится, что это когда-то называлось «крыльцо вислое»?","choices":["балкон","вестибюль","подъезд","навес","козырёк."],"key":"А","review":["Вислое крыльцо","Разбери старое выражение. «Крыльцо» обозначает площадку перед входом, а «вислое» подсказывает, что она словно висит над землёй.","Площадка, которая выступает из стены выше земли и на которую можно выйти, — балкон. Из вариантов это лучше всего подходит к старому описанию."]},{"author":"И. Иткин","question":"Какой из этих сборников рассказов был издан вскоре после сборника с похожим названием?","choices":["«Дважды рассказанные истории» Натаниэля Готорна","«Светлячок и другие рассказы» Харуки Мураками","«Рассказы из другого кармана» Карела Чапека","«Благородный жулик» О. Генри","«Белка в колесе» Александра Котова."],"key":"В","review":["Похожие названия сборников","В названии «Рассказы из другого кармана» слово «другого» заставляет спросить, был ли ещё один карман. Так можно найти вероятное название предыдущей книги.","У Карела Чапека сначала вышли «Рассказы из одного кармана», а затем «Рассказы из другого кармана». Оба сборника изданы в 1929 году."]},{"author":"Е. Бикмаев","question":"Вставьте пропущенное слово в загадку.\nХодит по двору …,\nРазгребает лапкой сор,\nРасправляет с шумом крылья\nИ садится на забор.","choices":["<em>петух</em>","<em>журавль</em>","<em>драчун</em>","<em>будильник</em>","<em>светильник</em>."],"key":"Г","review":["Загадка о дворе","По движениям и месту действия узнай петуха. Теперь попробуй описать его одним словом, намекнув на то, что он делает рано утром.","Петушиный крик будит людей, поэтому в загадке петух — «будильник». Слово даёт ещё одну подсказку к отгадке."]},{"author":"Е. Бикмаев","question":"У Жени есть пять карточек, на которых написаны звуки: на белой <em>—</em> [г], на трёх красных <em>—</em> [о], [у] и [р], на зелёной <em>—</em> [с’т’]. Сколько различно пишущихся слов сможет составить Женя, поставив на первое место белую карточку, на последнее <em>—</em> зелёную, а между ними <em>—</em> две красные карточки?","choices":["одно","два","три","четыре","пять."],"key":"Г","review":["Карточки со звуками","Расставь между [г] и [с’т’] две разные красные карточки. К знакомым словам ведут три пары звуков — [о][р], [р][о] и [р][у].","Первые две пары дают «горсть» и «гроздь». С третьей парой можно записать «грусть» и «груздь» — эти слова звучат одинаково. Всего четыре разных написания."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
